<script setup>
import { computed } from 'vue';
import { Button, Field } from './ui/index.js';
import { isSensitiveProperty } from './task-properties.js';
const props=defineProps({rows:{type:Array,required:true},error:String,disabled:Boolean});
const emit=defineEmits(['add','remove']);
const presets=computed(()=>props.rows.filter(row=>row.preset));
const custom=computed(()=>props.rows.filter(row=>!row.preset));
function rename(row,value){row.key=value;row.revealed=false;}
const hidden=row=>isSensitiveProperty(row.key)&&!row.revealed;
const maskText=value=>String(value || '').replace(/[^\r\n]/g,'•');
</script>
<template>
 <div class="task-properties-editor">
  <p class="muted property-guidance">仅当脚本使用 <code>${__P(属性名,默认值)}</code> 读取时生效。并发是每执行节点的值。常用参数留空则沿用环境或脚本。</p>
  <p v-if="error" class="field-error" role="alert">{{ error }}</p>
  <fieldset class="property-preset-grid" :disabled="disabled"><div v-for="row in presets" :key="row.id" class="property-preset" :class="{'property-cookie':row.key==='cookie'}"><div class="property-label"><label :for="`run-property-${row.id}`">{{ row.label }}</label><code>{{ row.key }}</code></div><div class="property-value"><div class="property-input" :class="{masked:hidden(row)}"><textarea :id="`run-property-${row.id}`" v-model="row.value" rows="1" :aria-label="`${row.key} 参数值`" :data-masked="hidden(row) ? 'true' : undefined" :placeholder="row.placeholder" :inputmode="row.key==='cookie' ? undefined : 'numeric'" autocomplete="off"/><span v-if="hidden(row)" class="secret-overlay" aria-hidden="true">{{ maskText(row.value) }}</span></div><Button v-if="isSensitiveProperty(row.key)" type="button" :aria-label="`${row.revealed ? '隐藏' : '显示'} ${row.key}`" @click="row.revealed=!row.revealed">{{ row.revealed ? '隐藏' : '显示' }}</Button></div><small class="field-hint">{{ row.hint }}</small></div></fieldset>
  <div class="custom-property-heading"><div><h4>自定义属性</h4><p class="muted">同名属性覆盖环境值；自定义空字符串表示明确清空该值。</p></div><Button type="button" :disabled="disabled" @click="emit('add')">添加自定义属性</Button></div>
  <fieldset class="custom-property-rows" :disabled="disabled"><div v-for="(row,index) in custom" :key="row.id" class="custom-property-row"><Field label="Key"><input :value="row.key" :aria-label="`第 ${index+1} 个自定义属性名称`" class="mono" placeholder="例如 region" @input="rename(row,$event.target.value)"/></Field><Field label="Value"><div class="property-value"><div class="property-input" :class="{masked:hidden(row)}"><textarea v-model="row.value" rows="2" :aria-label="`第 ${index+1} 个自定义属性值`" :data-masked="hidden(row) ? 'true' : undefined" placeholder="可填写多行，按原值传递" autocomplete="off"/><span v-if="hidden(row)" class="secret-overlay" aria-hidden="true">{{ maskText(row.value) }}</span></div><Button v-if="isSensitiveProperty(row.key)" type="button" :aria-label="`${row.revealed ? '隐藏' : '显示'}自定义属性 ${index+1}`" @click="row.revealed=!row.revealed">{{ row.revealed ? '隐藏' : '显示' }}</Button></div></Field><Button type="button" variant="danger-outline" :aria-label="`删除自定义属性 ${index+1}`" @click="emit('remove',row.id)">删除</Button></div></fieldset>
 </div>
</template>
<style scoped>
.property-guidance{font-size:12px;line-height:1.8;margin:0 0 16px}.property-preset-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:0;padding:0;border:0;min-width:0}.property-preset{min-width:0;padding:12px;background:var(--surface-alt);border:1px solid var(--border);border-radius:8px}.property-cookie{grid-column:1/-1}.property-label{display:flex;gap:9px;align-items:center;justify-content:space-between;margin-bottom:9px;font-size:12px}.property-label code{color:var(--muted);font-size:11px}.property-value{display:flex;gap:8px;align-items:start;min-width:0}.property-input{position:relative;min-width:0;flex:1}.property-input>textarea{display:block;width:100%;min-width:0;font-size:12px;line-height:1.5;resize:vertical;white-space:pre-wrap}.masked>textarea{color:transparent;caret-color:var(--text)}.masked>textarea::selection{color:transparent}.secret-overlay{position:absolute;inset:1px;padding:8px 10px;font-size:12px;line-height:1.5;white-space:pre-wrap;overflow:hidden;overflow-wrap:anywhere;pointer-events:none;color:var(--text)}@supports(-webkit-text-security:disc){.masked>textarea{-webkit-text-security:disc;color:var(--text)}.masked>textarea::selection{color:var(--text)}.masked>.secret-overlay{display:none}}.property-value>.button{flex:none;font-size:11px}.field-hint{display:block;font-size:11px;line-height:1.7;margin-top:7px}.custom-property-heading{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin:22px 0 12px}.custom-property-heading h4{margin:0;font-size:13px}.custom-property-heading p{font-size:11px;margin:6px 0 0}.custom-property-rows{border:0;padding:0;margin:0;min-width:0}.custom-property-row{display:grid;grid-template-columns:minmax(120px,.75fr) minmax(0,1.6fr) auto;gap:10px;align-items:start;padding:12px 0;border-top:1px solid var(--border)}.custom-property-row>.button{margin-top:24px}.custom-property-row .field{margin:0;min-width:0}.custom-property-row .field>input{width:100%;font-size:12px}@media(max-width:800px){.property-preset-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){.property-preset-grid{grid-template-columns:minmax(0,1fr)}.custom-property-row{grid-template-columns:minmax(0,1fr) auto}.custom-property-row>.field:first-child{grid-column:1/-1}.custom-property-row>.button{margin-top:24px}.property-label{flex-wrap:wrap}}
</style>
